CREATE OR REPLACE FUNCTION app.attachment_path_org(p_name text)
 RETURNS uuid
 LANGUAGE plpgsql
 STABLE
 SET search_path TO 'pg_catalog', 'public', 'app', 'storage'
AS $function$
declare
  v_root text;
begin
  v_root := split_part(coalesce(p_name, ''), '/', 1);
  if v_root = '' then return null; end if;
  return v_root::uuid;
exception when invalid_text_representation then
  return null;
end;
$function$

CREATE OR REPLACE FUNCTION app.audit_row()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'app', 'auth'
AS $function$
declare
  jn jsonb;      -- new (ou old, em delete)
  jo jsonb;      -- old (em update/delete)
  v_action text;
begin
  jn := case when tg_op = 'DELETE' then to_jsonb(old) else to_jsonb(new) end;
  jo := case when tg_op in ('UPDATE','DELETE') then to_jsonb(old) else '{}'::jsonb end;

  if tg_op = 'INSERT' then
    v_action := 'insert';
  elsif tg_op = 'UPDATE' then
    if  (jn->>'deleted_at')   is not null and (jo->>'deleted_at')   is null then v_action := 'delete';
    elsif (jo->>'deleted_at') is not null and (jn->>'deleted_at')   is null then v_action := 'restore';
    elsif (jn->>'finalized_at') is not null and (jo->>'finalized_at') is null then v_action := 'finalize';
    else v_action := 'update';
    end if;
  else
    v_action := 'delete';
  end if;

  insert into public.audit_logs(organization_id, user_id, patient_id, encounter_id,
                                module, record_id, action, new_value, created_at)
  values (nullif(jn->>'organization_id','')::uuid, auth.uid(),
          nullif(jn->>'patient_id','')::uuid, nullif(jn->>'encounter_id','')::uuid,
          tg_table_name, nullif(jn->>'id','')::uuid, v_action, jn, now());
  return null; -- AFTER trigger
end $function$

CREATE OR REPLACE FUNCTION app.bump_version()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'public', 'app', 'auth'
AS $function$
begin
  if new.organization_id is distinct from old.organization_id then
    raise exception 'O ambiente de um registro não pode ser alterado.'
      using errcode = 'check_violation';
  end if;

  -- Ignora qualquer version enviada pelo cliente. Só o banco incrementa.
  new.version := coalesce(old.version, 1) + 1;
  new.updated_by := coalesce(auth.uid(), old.updated_by);
  new.updated_at := now();
  return new;
end
$function$

CREATE OR REPLACE FUNCTION app.can_access_addendum_parent(p_org uuid, p_table text, p_parent uuid)
 RETURNS boolean
 LANGUAGE plpgsql
 STABLE
 SET search_path TO 'pg_catalog', 'public', 'app', 'auth'
AS $function$
declare
  permitido boolean := false;
begin
  if app.module_for_table(p_table) is null or p_table in ('patients','appointments','drafts') then
    return false;
  end if;

  execute format(
    'select exists (select 1 from public.%I where id = $1 and organization_id = $2)',
    p_table
  ) into permitido using p_parent, p_org;
  return coalesce(permitido, false);
end
$function$

CREATE OR REPLACE FUNCTION app.guard_explicit_org_share()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'public', 'app', 'auth'
AS $function$
begin
  if tg_op = 'DELETE' then
    raise exception 'Revogue o compartilhamento; seu histórico não pode ser apagado.'
      using errcode = 'check_violation';
  end if;
  if tg_op = 'UPDATE' then
    if new.id is distinct from old.id
       or new.org_origem is distinct from old.org_origem
       or new.org_destino is distinct from old.org_destino
       or new.criado_por is distinct from old.criado_por
       or new.criado_em is distinct from old.criado_em then
      raise exception 'Origem, destino e autoria original do compartilhamento são imutáveis.'
        using errcode = 'check_violation';
    end if;
    -- Manutenção não autoriza nem amplia escopo: só desativa um prazo vencido.
    if old.ativo and not new.ativo and old.expira_em <= statement_timestamp()
       and new.expirado_em is not null
       and (to_jsonb(new) - array['ativo','expirado_em']) =
           (to_jsonb(old) - array['ativo','expirado_em']) then
      return new;
    end if;
  end if;
  if auth.uid() is null or not app.eh_programador() then
    raise exception 'Apenas o programador pode autorizar ou revogar acesso entre clínicas.'
      using errcode = 'insufficient_privilege';
  end if;
  if new.ativo and (
     new.autorizado_por is distinct from auth.uid()
     or new.expira_em <= statement_timestamp()
     or new.autorizado_em is distinct from statement_timestamp()) then
    raise exception 'A autorização exige programador autenticado e prazo futuro explícito.'
      using errcode = 'check_violation';
  end if;
  return new;
end
$function$

CREATE OR REPLACE FUNCTION app.guard_organization_scope()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'public', 'app', 'auth'
AS $function$
declare
  old_row jsonb := to_jsonb(old);
  new_row jsonb := to_jsonb(new);
begin
  if new.organization_id is distinct from old.organization_id then
    raise exception 'O ambiente de um registro não pode ser alterado.'
      using errcode = 'check_violation';
  end if;
  if old_row ? 'created_by'
     and (new_row -> 'created_by') is distinct from (old_row -> 'created_by') then
    raise exception 'A autoria original de um registro não pode ser alterada.'
      using errcode = 'check_violation';
  end if;
  if old_row ? 'user_id'
     and (new_row -> 'user_id') is distinct from (old_row -> 'user_id') then
    raise exception 'O usuário vinculado ao registro não pode ser alterado.'
      using errcode = 'check_violation';
  end if;
  if old_row ? 'role'
     and (new_row -> 'role') is distinct from (old_row -> 'role') then
    raise exception 'O papel de um vínculo não pode ser alterado; desative e recrie o vínculo.'
      using errcode = 'check_violation';
  end if;
  return new;
end
$function$

CREATE OR REPLACE FUNCTION app.legacy_dependency_count(p_table text, p_target uuid)
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'app', 'auth'
AS $function$
declare
  v_table text;
  v_column text;
  v_total integer := 0;
  v_count integer;
begin
  if p_table = 'patients' then
    select count(*) into v_count from public.encounters
     where patient_id = p_target and deleted_at is null;
    v_total := v_total + v_count;
    v_column := 'patient_id';
  elsif p_table = 'encounters' then
    v_column := 'encounter_id';
  else
    raise exception 'legacy_dependency_table_invalid';
  end if;

  foreach v_table in array array[
    'appointments','preanesthetic_assessments','consultations',
    'anesthesia_records','recovery_records','risk_assessments','consents',
    'prescriptions','documents','finance_entries','quotes'
  ] loop
    execute format(
      'select count(*) from public.%I where %I = $1 and deleted_at is null',
      v_table, v_column
    ) into v_count using p_target;
    v_total := v_total + v_count;
  end loop;

  if p_table = 'patients' then
    select count(*) into v_count from public.addenda where patient_id = p_target;
    v_total := v_total + v_count;
    select count(*) into v_count from public.attachments
     where patient_id = p_target and deleted_at is null;
    v_total := v_total + v_count;
  else
    select count(*) into v_count from public.addenda where encounter_id = p_target;
    v_total := v_total + v_count;
    select count(*) into v_count from public.attachments
     where encounter_id = p_target and deleted_at is null;
    v_total := v_total + v_count;
    select count(*) into v_count from public.anesthesia_timeline_events
     where encounter_id = p_target and deleted_at is null;
    v_total := v_total + v_count;
  end if;
  return v_total;
end
$function$

CREATE OR REPLACE FUNCTION app.legacy_encounter_key(p_data jsonb)
 RETURNS text
 LANGUAGE plpgsql
 IMMUTABLE PARALLEL SAFE
 SET search_path TO 'pg_catalog', 'public', 'app'
AS $function$
declare
  v_patient text := app.legacy_patient_key(p_data);
  v_procedure text := public.med_normalizar(
    coalesce(nullif(p_data->>'procedimento', ''), p_data->>'cirurgia', '')
  );
  v_date date := app.legacy_date(p_data->>'data');
begin
  if v_patient is null or v_procedure = '' then return null; end if;
  return v_patient || '|' || coalesce(v_date::text, '') || '|' || v_procedure;
end
$function$

CREATE OR REPLACE FUNCTION app.legacy_ensure_encounter(p_org uuid, p_patient uuid, p_data jsonb)
 RETURNS TABLE(out_target_id uuid, out_legacy_id text, out_hash text, out_version integer, out_created boolean)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'app', 'auth'
AS $function$
declare
  v_key text := app.legacy_encounter_key(p_data);
  v_id uuid;
  v_data jsonb;
  v_version integer;
  v_deleted timestamptz;
  v_created boolean := false;
begin
  if v_key is null or p_patient is null then return; end if;

  insert into public.encounters(
    organization_id, legacy_id, patient_id, procedimento, data_prevista,
    convenio, status, data
  ) values (
    p_org, v_key, p_patient,
    coalesce(nullif(p_data->>'procedimento', ''), nullif(p_data->>'cirurgia', '')),
    app.legacy_date(p_data->>'data'),
    coalesce(nullif(p_data->>'convenio', ''), nullif(p_data->>'paciente_convenio', ''),
             nullif(p_data#>>'{paciente,convenio}', '')),
    'migrado', jsonb_build_object('origem', 'legacy_b2')
  )
  on conflict (organization_id, legacy_id) do nothing
  returning id, data, version, deleted_at
       into v_id, v_data, v_version, v_deleted;
  v_created := found;

  if v_id is null then
    select e.id, e.data, e.version, e.deleted_at
      into v_id, v_data, v_version, v_deleted
      from public.encounters e
     where e.organization_id = p_org and e.legacy_id = v_key
     for update;
  end if;
  if v_id is null then raise exception 'legacy_encounter_target_missing'; end if;
  if v_deleted is not null then raise exception 'legacy_encounter_target_deleted'; end if;

  return query select v_id, v_key, app.legacy_json_hash(v_data), v_version, v_created;
end
$function$

CREATE OR REPLACE FUNCTION app.legacy_ensure_patient(p_org uuid, p_data jsonb, p_primary boolean DEFAULT false)
 RETURNS TABLE(out_target_id uuid, out_legacy_id text, out_hash text, out_version integer, out_created boolean)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'app', 'auth'
AS $function$
declare
  v_key text := app.legacy_patient_key(p_data);
  v_name text := app.legacy_patient_name(p_data);
  v_payload jsonb := case when p_primary then coalesce(p_data, '{}'::jsonb)
                          else jsonb_build_object('origem', 'legacy_b2') end;
  v_id uuid;
  v_data jsonb;
  v_version integer;
  v_deleted timestamptz;
  v_created boolean := false;
  v_birth date;
  v_cpf text;
begin
  if v_key is null then return; end if;
  v_birth := app.legacy_date(coalesce(
    p_data->>'paciente_nasc', p_data->>'nascimento', p_data#>>'{paciente,nascimento}'
  ));
  v_cpf := regexp_replace(
    coalesce(p_data->>'cpf', p_data->>'paciente_cpf', p_data#>>'{paciente,cpf}', ''),
    '[^0-9]', '', 'g'
  );
  if char_length(v_cpf) < 11 then v_cpf := null; end if;

  insert into public.patients(
    organization_id, legacy_id, nome, nascimento, cpf, prontuario,
    convenio, telefone, sexo, data
  ) values (
    p_org, v_key, coalesce(nullif(v_name, ''), 'Sem nome'), v_birth, v_cpf,
    coalesce(nullif(p_data->>'prontuario', ''), nullif(p_data#>>'{paciente,prontuario}', '')),
    coalesce(nullif(p_data->>'convenio', ''), nullif(p_data->>'paciente_convenio', ''),
             nullif(p_data#>>'{paciente,convenio}', '')),
    coalesce(nullif(p_data->>'telefone', ''), nullif(p_data#>>'{paciente,telefone}', '')),
    coalesce(nullif(p_data->>'sexo', ''), nullif(p_data#>>'{paciente,sexo}', '')),
    v_payload
  )
  on conflict (organization_id, legacy_id) do nothing
  returning id, data, version, deleted_at
       into v_id, v_data, v_version, v_deleted;
  v_created := found;

  if v_id is null then
    select p.id, p.data, p.version, p.deleted_at
      into v_id, v_data, v_version, v_deleted
      from public.patients p
     where p.organization_id = p_org and p.legacy_id = v_key
     for update;
  end if;
  if v_id is null then raise exception 'legacy_patient_target_missing'; end if;
  if v_deleted is not null then raise exception 'legacy_patient_target_deleted'; end if;

  return query select v_id, v_key, app.legacy_json_hash(v_data), v_version, v_created;
end
$function$

CREATE OR REPLACE FUNCTION app.legacy_patient_key(p_data jsonb)
 RETURNS text
 LANGUAGE plpgsql
 IMMUTABLE PARALLEL SAFE
 SET search_path TO 'pg_catalog', 'public', 'app'
AS $function$
declare
  v_name text := public.med_normalizar(app.legacy_patient_name(p_data));
  v_cpf text := regexp_replace(
    coalesce(p_data->>'cpf', p_data->>'paciente_cpf', p_data#>>'{paciente,cpf}', ''),
    '[^0-9]', '', 'g'
  );
begin
  if char_length(v_name) >= 3 then return 'nome:' || v_name; end if;
  if char_length(v_cpf) >= 11 then return 'cpf:' || v_cpf; end if;
  return null;
end
$function$

CREATE OR REPLACE FUNCTION app.legacy_primary_dependency_count(p_table text, p_target uuid)
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'app', 'auth'
AS $function$
declare
  v_total integer := 0;
  v_count integer;
begin
  select count(*) into v_count
    from public.addenda
   where parent_table = p_table and parent_id = p_target;
  v_total := v_total + v_count;

  if p_table = 'preanesthetic_assessments' then
    select count(*) into v_count
      from public.anesthesia_records
     where preanesthetic_assessment_id = p_target and deleted_at is null;
    v_total := v_total + v_count;
  elsif p_table = 'anesthesia_records' then
    select count(*) into v_count
      from public.recovery_records
     where anesthesia_record_id = p_target and deleted_at is null;
    v_total := v_total + v_count;
    select count(*) into v_count
      from public.anesthesia_timeline_events
     where anesthesia_record_id = p_target and deleted_at is null;
    v_total := v_total + v_count;
  end if;
  return v_total;
end
$function$

CREATE OR REPLACE FUNCTION app.stamp_and_validate_addendum()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'public', 'app', 'auth'
AS $function$
declare
  parent_org uuid;
  parent_encounter uuid;
  parent_patient uuid;
  parent_finalized timestamptz;
  parent_legacy text;
begin
  if app.module_for_table(new.parent_table) is null
     or new.parent_table in ('patients','appointments','drafts','finance_entries','quotes') then
    raise exception 'Tabela pai inválida para adendo.'
      using errcode = 'check_violation';
  end if;

  execute format(
    'select organization_id, encounter_id, patient_id, finalized_at, legacy_id '
    'from public.%I where id = $1',
    new.parent_table
  ) into parent_org, parent_encounter, parent_patient, parent_finalized, parent_legacy
    using new.parent_id;

  if parent_org is null then
    raise exception 'Registro pai do adendo não encontrado.'
      using errcode = 'foreign_key_violation';
  end if;
  if new.organization_id is distinct from parent_org then
    raise exception 'Adendo e registro pai devem pertencer ao mesmo ambiente.'
      using errcode = 'check_violation';
  end if;
  if parent_finalized is null then
    raise exception 'Adendos só podem corrigir registros finalizados.'
      using errcode = 'check_violation';
  end if;

  new.encounter_id := parent_encounter;
  new.patient_id := parent_patient;
  new.parent_legacy_id := parent_legacy;
  new.created_by := auth.uid();
  new.author_id := auth.uid();
  new.created_at := now();
  new.reason := coalesce(nullif(btrim(new.reason), ''), 'correcao');
  new.legacy_id := coalesce(nullif(btrim(new.legacy_id), ''), new.id::text);
  return new;
end
$function$

CREATE OR REPLACE FUNCTION app.stamp_attachment_metadata()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'app', 'auth'
AS $function$
declare
  v_uid uuid := auth.uid();
  v_path_org uuid := app.attachment_path_org(new.storage_path);
begin
  if v_uid is null then
    raise exception 'attachment requires authenticated user';
  end if;
  if v_path_org is null or v_path_org is distinct from new.organization_id then
    raise exception 'attachment path organization mismatch';
  end if;
  if not app.attachment_path_owned(new.storage_path, new.organization_id, v_uid) then
    raise exception 'attachment path owner mismatch';
  end if;
  if split_part(new.storage_path, '/', 3) <> 'anexos' then
    raise exception 'attachment metadata requires an anexos path';
  end if;
  if not exists (
    select 1 from storage.objects o
     where o.bucket_id = 'clinical-attachments'
       and o.name = new.storage_path
  ) then
    raise exception 'attachment storage object not found';
  end if;
  if new.patient_id is not null and not exists (
    select 1 from public.patients p
     where p.id = new.patient_id and p.organization_id = new.organization_id
  ) then
    raise exception 'attachment patient organization mismatch';
  end if;
  if new.encounter_id is not null and not exists (
    select 1 from public.encounters e
     where e.id = new.encounter_id and e.organization_id = new.organization_id
  ) then
    raise exception 'attachment encounter organization mismatch';
  end if;
  if new.hash is not null and new.hash !~ '^[0-9a-f]{64}$' then
    raise exception 'attachment hash must be sha256 hex';
  end if;
  new.uploaded_by := v_uid;
  new.uploaded_at := now();
  return new;
end;
$function$

CREATE OR REPLACE FUNCTION app.stamp_created()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'public', 'app', 'auth'
AS $function$
declare
  v_uid uuid := auth.uid();
begin
  if v_uid is not null then
    new.created_by := v_uid;
    new.updated_by := v_uid;
  end if;
  return new;
end
$function$

CREATE OR REPLACE FUNCTION app.stamp_draft()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'public', 'app', 'auth'
AS $function$
begin
  new.user_id := auth.uid();
  new.updated_by := auth.uid();
  new.created_at := now();
  new.updated_at := new.created_at;
  new.version := 1;
  return new;
end
$function$

CREATE OR REPLACE FUNCTION app.stamp_finalization()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'public', 'app', 'auth'
AS $function$
begin
  if tg_op = 'INSERT' then
    if new.finalized_at is not null or lower(coalesce(new.status, '')) = 'finalized' then
      new.finalized_at := now();
      new.finalized_by := auth.uid();
      new.status := 'finalized';
    else
      new.finalized_by := null;
    end if;
    return new;
  end if;

  if old.finalized_at is null then
    if new.finalized_at is not null or lower(coalesce(new.status, '')) = 'finalized' then
      new.finalized_at := now();
      new.finalized_by := auth.uid();
      new.status := 'finalized';
    else
      new.finalized_by := old.finalized_by;
    end if;
  end if;
  return new;
end
$function$

CREATE OR REPLACE FUNCTION app.stamp_retification_cas()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'public', 'app', 'auth'
AS $function$
declare
  proposed jsonb;
  prior public.addenda%rowtype;
  head_id text := '';
  head_revision bigint := 0;
  outcome text;
begin
  -- Nem INSERT direto permite ao cliente forjar a coluna interna.
  new.retification_revision := null;
  if not (new.data ? 'retificacao') then return new; end if;
  proposed := new.data->'retificacao';
  if new.reason not in ('correcao','retificacao')
     or length(new.legacy_id) > 180
     or jsonb_typeof(proposed) is distinct from 'object'
     or proposed->'schema' is distinct from '1'::jsonb
     or jsonb_typeof(proposed->'baseAdendoId') is distinct from 'string'
     or length(proposed->>'baseAdendoId') > 180
     or jsonb_typeof(proposed->'campos') is distinct from 'object'
     or proposed->'campos' = '{}'::jsonb
     or proposed - array['schema','baseAdendoId','campos'] <> '{}'::jsonb
     or octet_length(proposed::text) > 262144
     or not app.valid_retification_fields(proposed->'campos') then
    raise exception 'Proposta de retificação inválida.' using errcode = 'check_violation';
  end if;

  -- O stamp anterior valida pai finalizado e deriva organização/FKs/autor/hora.
  -- A defesa explícita impede que o lock revele uma cabeça fora do escopo RLS.
  if auth.uid() is null
     or not exists (select 1 from app.org_ids() as o(id) where o.id = new.organization_id)
     or not (app.has_role(new.organization_id,array['gestor'])
       or app.pode_editar_modulo(new.organization_id,app.module_for_table(new.parent_table)))
     or not app.can_access_addendum_parent(new.organization_id,new.parent_table,new.parent_id) then
    raise exception 'Retificação não autorizada.' using errcode = 'insufficient_privilege';
  end if;

  -- PostgREST usa READ COMMITTED. Uma transação com snapshot fixo deve repetir
  -- inteira, em vez de aceitar uma cabeça que ficou antiga durante a espera.
  if current_setting('transaction_isolation') <> 'read committed' then
    raise exception 'Repita a retificação em READ COMMITTED.' using errcode = 'serialization_failure';
  end if;
  -- O rótulo de autoria também vem da identidade autenticada, nunca de texto
  -- informado pelo aparelho. Ausência de perfil usa o UUID canônico.
  new.data := jsonb_set(new.data,'{autor_exibicao}',to_jsonb(coalesce(
    (select nullif(btrim(p.nome),'') from public.profiles p where p.id = auth.uid()),auth.uid()::text)));
  -- Serializa também UUID reutilizado simultaneamente em dois pais distintos.
  -- A identidade da operação é travada antes da identidade da cadeia.
  perform pg_advisory_xact_lock(hashtextextended(
    new.organization_id::text || '/addenda-operation/' || new.legacy_id,1));
  -- Lock transacional por org/tabela/UUID, sem UPDATE ou privilégio de UPDATE
  -- no pai imutável. Colisões do hash só serializam pais independentes.
  perform pg_advisory_xact_lock(hashtextextended(
    new.organization_id::text || '/' || new.parent_table || '/' || new.parent_id::text,0));

  -- Comando posterior ao lock: vê a transação concorrente recém-confirmada.
  -- Mesmo UUID de operação nunca confirma outra proposta por ignore-duplicates.
  select * into prior from public.addenda
   where organization_id = new.organization_id and legacy_id = new.legacy_id;
  if found then
    if prior.parent_table is distinct from new.parent_table
       or prior.parent_id is distinct from new.parent_id
       or prior.texto is distinct from new.texto
       or prior.reason is distinct from new.reason
       or prior.author_id is distinct from new.author_id
       or (prior.data->'retificacao') - array['status','revisao','baseAtualId'] is distinct from proposed then
      raise exception 'Identificador de retificação reutilizado para outra proposta.'
        using errcode = 'check_violation';
    end if;
    new.data := jsonb_set(new.data,'{retificacao}',prior.data->'retificacao');
    new.retification_revision := prior.retification_revision;
    return new;
  end if;

  select legacy_id,retification_revision into head_id,head_revision
    from public.addenda
   where organization_id = new.organization_id and parent_table = new.parent_table
     and parent_id = new.parent_id and retification_revision is not null
   order by retification_revision desc limit 1;
  head_id := coalesce(head_id,'');
  head_revision := coalesce(head_revision,0);
  outcome := case when proposed->>'baseAdendoId' = head_id then 'accepted' else 'conflict' end;
  if outcome = 'accepted' then new.retification_revision := head_revision+1; end if;
  new.data := jsonb_set(new.data,'{retificacao}',proposed || jsonb_build_object(
    'status',outcome,'revisao',coalesce(new.retification_revision,head_revision),'baseAtualId',head_id));
  return new;
end
$function$

CREATE OR REPLACE FUNCTION app.stamp_sync_conflict()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'public', 'app', 'auth'
AS $function$
begin
  new.created_by := auth.uid();
  new.created_at := now();
  new.updated_at := new.created_at;
  new.status := 'pending';
  new.resolution := null;
  new.resolved_by := null;
  new.resolved_at := null;
  return new;
end
$function$

CREATE OR REPLACE FUNCTION app.valid_retification_fields(p_value jsonb, p_depth integer DEFAULT 0)
 RETURNS boolean
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO 'pg_catalog', 'public', 'app'
AS $function$
declare
  k text;
  v jsonb;
  kind text := jsonb_typeof(p_value);
begin
  if p_depth is null or p_depth < 0 or p_depth > 16 or kind is null then return false; end if;
  if kind = 'object' then
    for k, v in select key, value from jsonb_each(p_value) loop
      if lower(k) = any(array[
        '__proto__','constructor','prototype','id','patient_id','patientid',
        'patientref','patientkey','caseid','casekey','encounter_id','encounterid',
        'organization_id','organizationid','orgid','legacy_id','version',
        'created_by','created_at','updated_at','updated_by','finalized_at','finalized_by','signed_at','signed_by',
        'author_id','authorid','user_id','userid','uid','deviceid','tabid','sessionid',
        'access_token','refresh_token','dataurl','sig_dataurl','carimbo'
      ]) or left(lower(k),10) = 'assinatura' or left(lower(k),9) = 'signature'
         or left(lower(k),15) = 'data_assinatura' then
        return false;
      end if;
      if left(k,1) = '_' and not (p_depth = 0 and k = any(array[
        '_medsLista','_procsExtra','_labExtras','_premedSel',
        '_seguimentos','_procsRealizados','_resumo'
      ])) then return false; end if;
      if not app.valid_retification_fields(v,p_depth+1) then return false; end if;
    end loop;
  elsif kind = 'array' then
    for v in select value from jsonb_array_elements(p_value) loop
      if not app.valid_retification_fields(v,p_depth+1) then return false; end if;
    end loop;
  end if;
  return true;
end
$function$

CREATE OR REPLACE FUNCTION public.add_member(p_org uuid, p_email text, p_role text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'app', 'auth'
AS $function$
declare
  v_uid uuid;
begin
  -- 1) Só o gestor da organização pode adicionar membros
  if not app.has_role(p_org, array['gestor']) then
    raise exception 'Apenas o gestor da organização pode adicionar membros.';
  end if;

  -- 2) Papel válido
  if p_role not in ('gestor','anestesiologista','cirurgiao','auxiliar','financeiro','empresa') then
    raise exception 'Papel inválido: %', p_role;
  end if;

  -- 3) Encontra o usuário pelo e-mail (precisa já ter conta na nuvem)
  select id into v_uid from auth.users where lower(email) = lower(trim(p_email)) limit 1;
  if v_uid is null then
    raise exception 'Nenhuma conta na nuvem com o e-mail %. Peça para a pessoa criar a conta primeiro (Entrar -> Criar conta).', p_email;
  end if;

  -- 4) Vincula com o papel (ativo) e torna esse o papel efetivo (único ativo)
  insert into public.organization_users(organization_id, user_id, role, ativo)
    values (p_org, v_uid, p_role, true)
    on conflict (organization_id, user_id, role) do update set ativo = true;
  update public.organization_users
    set ativo = false
    where organization_id = p_org and user_id = v_uid and role <> p_role;

  -- 5) Garante o profile
  insert into public.profiles(id, nome, email, funcao, ativo)
    values (v_uid,
            coalesce((select raw_user_meta_data->>'name' from auth.users where id = v_uid), split_part(p_email,'@',1)),
            p_email, p_role, true)
    on conflict (id) do update set ativo = true, funcao = p_role, email = excluded.email;

  return v_uid;
end;
$function$

CREATE OR REPLACE FUNCTION public.criar_minha_organizacao(p_nome text DEFAULT NULL::text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'app', 'auth'
AS $function$
declare
  v_uid   uuid := auth.uid();
  v_email text;
  v_org   uuid;
  v_nome  text;
begin
  if v_uid is null then
    raise exception 'Entre na nuvem antes de criar a sua clínica.';
  end if;

  select email into v_email from auth.users where id = v_uid;
  v_nome := coalesce(nullif(trim(p_nome), ''), 'Clínica de ' || coalesce(split_part(v_email, '@', 1), 'usuário'));

  -- (B) já é membro de alguma organização?
  select ou.organization_id into v_org
    from public.organization_users ou
   where ou.user_id = v_uid and ou.ativo = true
   order by ou.created_at asc
   limit 1;

  if v_org is not null then
    -- só assume se a organização estiver SEM gestor ativo (órfã)
    if exists (select 1 from public.organization_users g
                where g.organization_id = v_org and g.ativo = true and g.role = 'gestor') then
      raise exception 'Esta clínica já tem um gestor. Peça a ele para ajustar o seu papel em Equipe da nuvem.';
    end if;
    insert into public.organization_users(organization_id, user_id, role, ativo)
      values (v_org, v_uid, 'gestor', true)
      on conflict (organization_id, user_id, role) do update set ativo = true;
    update public.organization_users
       set ativo = false
     where organization_id = v_org and user_id = v_uid and role <> 'gestor';
  else
    -- (A) primeira organização desta conta
    insert into public.organizations(nome) values (v_nome) returning id into v_org;
    insert into public.organization_users(organization_id, user_id, role, ativo)
      values (v_org, v_uid, 'gestor', true);
  end if;

  insert into public.profiles(id, nome, email, funcao, ativo)
    values (v_uid, coalesce(split_part(v_email, '@', 1), 'usuário'), v_email, 'gestor', true)
    on conflict (id) do update set ativo = true, funcao = 'gestor',
                                   email = coalesce(excluded.email, public.profiles.email);
  return v_org;
end;
$function$

CREATE OR REPLACE FUNCTION public.prog_ack_legacy_source_change(p_registry_id uuid, p_reason text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'app', 'auth'
AS $function$
declare
  v_row public.legacy_document_registry%rowtype;
  v_status text;
begin
  if not app.eh_programador() then
    raise exception 'Apenas o programador pode reconhecer mudança no legado.'
      using errcode = 'insufficient_privilege';
  end if;
  if char_length(btrim(coalesce(p_reason, ''))) < 12 then
    raise exception 'Informe uma justificativa com pelo menos 12 caracteres.'
      using errcode = 'invalid_parameter_value';
  end if;
  select * into v_row from public.legacy_document_registry
   where id = p_registry_id for update;
  if v_row.id is null or v_row.status <> 'source_changed' or v_row.target_id is not null then
    raise exception 'A linha não está disponível para reconhecer a mudança.'
      using errcode = 'object_not_in_prerequisite_state';
  end if;
  v_status := case when v_row.target_table is null then 'unsupported'
                   when v_row.organization_id is not null then 'classified'
                   else 'quarantined' end;
  update public.legacy_document_registry
     set source_hash = observed_hash,
         source_updated_at = observed_updated_at,
         source_bytes = observed_bytes,
         status = v_status,
         last_error_code = null, last_error_at = null
   where id = p_registry_id;
  insert into public.legacy_migration_events(
    registry_id, programmer_id, action, previous_status, new_status,
    organization_id, reason, metadata
  ) values (
    p_registry_id, auth.uid(), 'ack_source_change', v_row.status, v_status,
    v_row.organization_id, btrim(p_reason),
    jsonb_build_object('hash_rebased', true)
  );
  return jsonb_build_object('registry_id', p_registry_id, 'status', v_status);
end
$function$

CREATE OR REPLACE FUNCTION public.prog_add_member(p_org uuid, p_email text, p_role text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'app', 'auth'
AS $function$
declare
  v_uid uuid;
begin
